\n  transition: all 0.3s;\n  background: #fafbfc;\n  cursor: pointer;\n}\n\n.file-drop-zone.dragover[_ngcontent-%COMP%] {\n  border-color: #667eea;\n  background: #eef2ff;\n  transform: scale(1.01);\n}\n\n.file-drop-content[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n}\n\n.file-icon[_ngcontent-%COMP%] {\n  font-size: 40px;\n}\n\n.btn-browse[_ngcontent-%COMP%] {\n  background: #f3f4f6;\n  border: 1px solid #d1d5db;\n  padding: 6px 16px;\n  border-radius: 6px;\n  cursor: pointer;\n  margin-top: 4px;\n}\n\n.file-formats[_ngcontent-%COMP%] {\n  display: flex;\n  gap: 6px;\n  flex-wrap: wrap;\n  justify-content: center;\n  margin-top: 8px;\n}\n\n.format-tag[_ngcontent-%COMP%] {\n  font-size: 10px;\n  font-weight: 600;\n  padding: 2px 8px;\n  border-radius: 4px;\n  background: #e0e7ff;\n  color: #4338ca;\n}\n\n.file-list[_ngcontent-%COMP%] {\n  margin-top: 12px;\n}\n\n.file-list[_ngcontent-%COMP%]   h4[_ngcontent-%COMP%] {\n  font-size: 0.9rem;\n  color: #1a2332;\n  margin-bottom: 8px;\n}\n\n.file-item[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 12px;\n  background: #f8fafc;\n  border-radius: 6px;\n  border-left: 3px solid #667eea;\n  margin-bottom: 6px;\n  flex-wrap: wrap;\n}\n\n.file-item.uploaded-item[_ngcontent-%COMP%] {\n  border-left-color: #10b981;\n}\n\n.file-name[_ngcontent-%COMP%] {\n  font-weight: 500;\n  font-size: 14px;\n  flex: 1;\n  min-width: 100px;\n}\n\n.file-size[_ngcontent-%COMP%] {\n  font-size: 12px;\n  color: #6b7a8f;\n}\n\n.file-date[_ngcontent-%COMP%] {\n  font-size: 12px;\n  color: #6b7a8f;\n}\n\n.file-icon-small[_ngcontent-%COMP%] {\n  font-size: 20px;\n}\n\n.btn-remove-file[_ngcontent-%COMP%] {\n  background: #fee2e2;\n  border: none;\n  border-radius: 4px;\n  color: #dc2626;\n  cursor: pointer;\n  padding: 2px 8px;\n  font-size: 14px;\n}\n\n.btn-remove-file[_ngcontent-%COMP%]:hover {\n  background: #fecaca;\n}\n\n.file-actions[_ngconten