import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MarcheService } from '../../services/marche.service';
import { PieceJointeService, PieceJointe } from '../../services/piece-jointe.service';
import { REGIONS, COMMUNES } from '../../data/regions.data';

@Component({
  selector: 'app-marche-form',
  templateUrl: './marche-form.component.html',
  styleUrls: ['./marche-form.component.scss']
})
export class MarcheFormComponent implements OnInit {
  marcheForm: FormGroup;
  isEditMode = false;
  marcheId: number | null = null;
  isLoading = false;

  regions = REGIONS;
  departements: any[] = [];
  communes: any[] = [];

  // ===== DÉCOMPTES =====
  decomptes: { numero: number; montant: number; date: string }[] = [];
  maxDecomptes = 20;

  // ===== RÉCEPTION =====
  typeReception: string = 'AUCUNE';
  dateReception: string = '';

  // ===== PIÈCES JOINTES =====
  fichiers: PieceJointe[] = [];
  fichiersSelectionnes: File[] = [];
  isDragging = false;
  espaceTotal = 10000000; // 10 000 Go en Mo
  espaceUtilise = 0;

  typeOptions = [
    { value: 'PRESTATION_SERVICE', label: 'Prestation de service' },
    { value: 'PRESTATION_INTELLECTUELLE', label: 'Prestation intellectuelle' },
    { value: 'FOURNITURE', label: 'Fourniture' },
    { value: 'TRAVAUX', label: 'Travaux' },
    { value: 'AUTRE', label: 'Autre' }
  ];

  statutOptions = [
    { value: 'EN_ATTENTE', label: 'En attente' },
    { value: 'ACTIF', label: 'Actif' },
    { value: 'ARCHIVE', label: 'Archivé' },
    { value: 'ANNULE', label: 'Annulé' }
  ];

  constructor(
    private fb: FormBuilder,
    private marcheService: MarcheService,
    private pieceJointeService: PieceJointeService,
    private route: ActivatedRoute,
    private router: Router
  ) {
    this.marcheForm = this.fb.group({
      reference: ['', Validators.required],
      objet: ['', Validators.required],
      type: ['', Validators.required],
      direction: ['', Validators.required],
      statut: ['EN_ATTENTE'],
      montant: [null, Validators.required],
      description: [''],
      region: [''],
      departement: [''],
      commune: ['']
    });
  }

  ngOnInit(): void {
    this.route.params.subscribe(params => {
      if (params['id']) {
        this.isEditMode = true;
        this.marcheId = +params['id'];
        this.loadMarche(this.marcheId);
        this.loadFiles(this.marcheId);
      }
    });

    this.marcheForm.get('region')?.valueChanges.subscribe((regionCode: string) => {
      if (regionCode) {
        const region = this.regions.find(r => r.code === regionCode);
        this.departements = region?.departements || [];
        this.marcheForm.get('departement')?.setValue('');
        this.marcheForm.get('commune')?.setValue('');
        this.communes = [];
      } else {
        this.departements = [];
        this.communes = [];
      }
    });

    this.marcheForm.get('departement')?.valueChanges.subscribe((deptCode: string) => {
      if (deptCode) {
        this.communes = COMMUNES[deptCode] || [];
        this.marcheForm.get('commune')?.setValue('');
      } else {
        this.communes = [];
      }
    });
  }

  onRegionSelect(event: any): void {
    const regionCode = event.target.value;
    if (regionCode) {
      const region = this.regions.find(r => r.code === regionCode);
      this.departements = region?.departements || [];
      this.marcheForm.get('departement')?.setValue('');
      this.marcheForm.get('commune')?.setValue('');
      this.communes = [];
    } else {
      this.departements = [];
      this.communes = [];
    }
  }

  onDepartementSelect(event: any): void {
    const deptCode = event.target.value;
    if (deptCode) {
      this.communes = COMMUNES[deptCode] || [];
      this.marcheForm.get('commune')?.setValue('');
    } else {
      this.communes = [];
    }
  }

  loadMarche(id: number): void {
    this.marcheService.getMarcheById(id).subscribe({
      next: (marche) => {
        this.marcheForm.patchValue(marche);
        if (marche.region) {
          const region = this.regions.find(r => r.code === marche.region);
          this.departements = region?.departements || [];
          this.marcheForm.get('region')?.setValue(marche.region);
        }
        if (marche.departement) {
          this.communes = COMMUNES[marche.departement] || [];
          this.marcheForm.get('departement')?.setValue(marche.departement);
        }
        if (marche.commune) {
          this.marcheForm.get('commune')?.setValue(marche.commune);
        }
        if (marche.decomptes) {
          this.decomptes = marche.decomptes;
        }
        if (marche.reception) {
          this.typeReception = marche.reception.typeReception;
          this.dateReception = marche.reception.dateReception || '';
        }
      },
      error: (error) => {
        console.error('Error loading marche:', error);
        alert('❌ Erreur lors du chargement du marché');
        this.router.navigate(['/marches']);
      }
    });
  }

  loadFiles(marcheId: number): void {
    this.pieceJointeService.getFiles(marcheId).subscribe({
      next: (files) => {
        this.fichiers = files;
        this.calculerEspace();
      },
      error: (error) => console.error('Erreur chargement fichiers:', error)
    });
  }

  // ===== GESTION DES DÉCOMPTES =====
  ajouterDecompte(): void {
    if (this.decomptes.length < this.maxDecomptes) {
      this.decomptes.push({
        numero: this.decomptes.length + 1,
        montant: 0,
        date: new Date().toISOString().split('T')[0]
      });
    } else {
      alert('Vous avez déjà atteint le maximum de 20 décomptes');
    }
  }

  supprimerDecompte(index: number): void {
    this.decomptes.splice(index, 1);
    this.decomptes.forEach((d, i) => d.numero = i + 1);
  }

  // ===== GESTION DE LA RÉCEPTION =====
  onTypeReceptionChange(): void {
    if (this.typeReception === 'AUCUNE') {
      this.dateReception = '';
    }
  }

  // ===== GESTION DES FICHIERS =====
  getIcone(type: string): string {
    const icones: { [key: string]: string } = {
      'pdf': '📄',
      'doc': '📝',
      'docx': '📝',
      'xls': '📊',
      'xlsx': '📊',
      'ppt': '📽️',
      'pptx': '📽️',
      'jpg': '🖼️',
      'jpeg': '🖼️',
      'png': '🖼️',
      'gif': '🖼️',
      'mp4': '🎬',
      'avi': '🎬',
      'mkv': '🎬',
      'mp3': '🎵',
      'zip': '📦',
      'rar': '📦',
      '7z': '📦',
      'txt': '📃',
      'default': '📎'
    };
    return icones[type] || icones['default'];
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging = true;
  }

  onDragLeave(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging = false;
  }

  onDropFile(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging = false;
    const files = event.dataTransfer?.files;
    if (files) {
      this.ajouterFichiers(files);
    }
  }

  onFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    const files = input.files;
    if (files) {
      this.ajouterFichiers(files);
    }
    input.value = '';
  }

  ajouterFichiers(files: FileList): void {
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      // Vérifier la taille (max 100MB par fichier)
      if (file.size > 100 * 1024 * 1024) {
        alert(`Le fichier ${file.name} dépasse 100MB`);
        continue;
      }
      this.fichiersSelectionnes.push(file);
      this.espaceUtilise += file.size;
    }
    this.calculerEspace();
  }

  removeFileSelection(index: number): void {
    const file = this.fichiersSelectionnes[index];
    this.espaceUtilise -= file.size;
    this.fichiersSelectionnes.splice(index, 1);
    this.calculerEspace();
  }

  supprimerFichier(marcheId: number, pieceId: number, index: number): void {
    if (confirm('Supprimer ce fichier ?')) {
      this.pieceJointeService.deleteFile(marcheId, pieceId).subscribe({
        next: () => {
          this.fichiers.splice(index, 1);
          this.calculerEspace();
        },
        error: (error) => console.error('Erreur suppression:', error)
      });
    }
  }

  telechargerFichier(marcheId: number, pieceId: number, nom: string): void {
    this.pieceJointeService.downloadFile(marcheId, pieceId).subscribe({
      next: (blob) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = nom;
        a.click();
        window.URL.revokeObjectURL(url);
      },
      error: (error) => console.error('Erreur téléchargement:', error)
    });
  }

  visualiserFichier(url: string): void {
    window.open(url, '_blank');
  }

  calculerEspace(): void {
    let total = 0;
    this.fichiers.forEach(f => total += f.taille);
    this.fichiersSelectionnes.forEach(f => total += f.size);
    this.espaceUtilise = total;
  }

  getEspaceUtilise(): string {
    return (this.espaceUtilise / (1024 * 1024 * 1024)).toFixed(2);
  }

  getEspaceTotal(): string {
    return '10 000';
  }

  getPourcentageEspace(): number {
    return (this.espaceUtilise / (this.espaceTotal * 1024 * 1024 * 1024)) * 100;
  }

  uploadFiles(marcheId: number): void {
    this.fichiersSelectionnes.forEach((file) => {
      this.pieceJointeService.uploadFile(marcheId, file).subscribe({
        next: (response) => {
          this.fichiers.push(response);
          this.calculerEspace();
        },
        error: (error) => console.error('Erreur upload:', error)
      });
    });
    this.fichiersSelectionnes = [];
  }

  onSubmit(): void {
    if (this.marcheForm.valid) {
      this.isLoading = true;
      const formValue = this.marcheForm.value;

      const marche = {
        reference: formValue.reference,
        objet: formValue.objet,
        type: formValue.type || 'AUTRE',
        direction: formValue.direction || '',
        statut: formValue.statut || 'EN_ATTENTE',
        montant: formValue.montant,
        description: formValue.description || '',
        region: formValue.region || '',
        departement: formValue.departement || '',
        commune: formValue.commune || '',
        titulaire: 'Non spécifié',
        sourceFinancement: 'Budget National',
        duree: '12 mois',
        dateCreation: new Date().toISOString(),
        decomptes: this.decomptes,
        reception: this.typeReception !== 'AUCUNE' ? {
          typeReception: this.typeReception,
          dateReception: this.dateReception
        } : null
      };

      if (this.isEditMode && this.marcheId) {
        this.marcheService.updateMarche(this.marcheId, marche).subscribe({
          next: (response) => {
            this.isLoading = false;
            this.uploadFiles(response.id);
            this.router.navigate(['/marches']);
          },
          error: (error) => {
            this.isLoading = false;
            console.error('Error updating marche:', error);
            alert('❌ Erreur lors de la mise à jour');
          }
        });
      } else {
        this.marcheService.createMarche(marche).subscribe({
          next: (response) => {
            this.isLoading = false;
            if (this.fichiersSelectionnes.length > 0) {
              this.uploadFiles(response.id);
            }
            this.router.navigate(['/marches']);
          },
          error: (error) => {
            this.isLoading = false;
            console.error('❌ Erreur création:', error);
            alert('❌ Erreur lors de la création');
          }
        });
      }
    }
  }

  goBack(): void {
    this.router.navigate(['/marches']);
  }
}
<div class="marche-form-container">
  <div class="form-header">
    <h2>{{ isEditMode ? '✏️ Éditer le Marché' : '📝 Nouveau Marché' }}</h2>
    <button class="btn btn-secondary" (click)="goBack()">← Retour</button>
  </div>

  <form [formGroup]="marcheForm" (ngSubmit)="onSubmit()">
    <div class="form-grid">

      <!-- ===== INFOS GÉNÉRALES ===== -->
      <div class="form-group">
        <label>📌 Référence *</label>
        <input type="text" formControlName="reference" placeholder="Ex: M-2024-001" class="form-control">
      </div>
      <div class="form-group">
        <label>📝 Objet du Marché *</label>
        <input type="text" formControlName="objet" placeholder="Titre du marché" class="form-control">
      </div>
      <div class="form-group">
        <label>📂 Type *</label>
        <select formControlName="type" class="form-control">
          <option value="">Sélectionnez un type</option>
          <option *ngFor="let opt of typeOptions" [value]="opt.value">{{ opt.label }}</option>
        </select>
      </div>
      <div class="form-group">
        <label>🏢 Direction *</label>
        <input type="text" formControlName="direction" placeholder="Ex: DSI, DAG, DAO..." class="form-control">
      </div>
      <div class="form-group">
        <label>📊 Statut</label>
        <select formControlName="statut" class="form-control">
          <option *ngFor="let opt of statutOptions" [value]="opt.value">{{ opt.label }}</option>
        </select>
      </div>
      <div class="form-group">
        <label>💰 Montant (FCFA) *</label>
        <input type="number" formControlName="montant" placeholder="0" class="form-control">
      </div>
      <div class="form-group full-width">
        <label>📄 Description</label>
        <textarea formControlName="description" rows="3" placeholder="Description du marché..." class="form-control"></textarea>
      </div>

      <!-- ===== LOCALISATION ===== -->
      <div class="form-group">
        <label>🗺️ Région</label>
        <select formControlName="region" (change)="onRegionSelect($event)" class="form-control">
          <option value="">Sélectionnez une région</option>
          <option *ngFor="let r of regions" [value]="r.code">{{ r.nom }}</option>
        </select>
      </div>
      <div class="form-group">
        <label>📍 Département</label>
        <select formControlName="departement" (change)="onDepartementSelect($event)" class="form-control" [disabled]="!departements.length">
          <option value="">Sélectionnez un département</option>
          <option *ngFor="let d of departements" [value]="d.code">{{ d.nom }}</option>
        </select>
      </div>
      <div class="form-group full-width">
        <label>🏘️ Commune</label>
        <select formControlName="commune" class="form-control" [disabled]="!communes.length">
          <option value="">Sélectionnez une commune</option>
          <option *ngFor="let c of communes" [value]="c.code">{{ c.nom }}</option>
        </select>
      </div>

      <!-- ===== DÉCOMPTES ===== -->
      <div class="form-group full-width" style="border-top: 2px dashed #e5e7eb; padding-top: 15px; margin-top: 10px;">
        <label style="font-size: 1rem; font-weight: 600; color: #1e3c72;">📊 Décomptes (1 à 20)</label>

        <div class="decompte-header">
          <span class="decompte-label">Nombre de décomptes : {{ decomptes.length }}/20</span>
          <button type="button" class="btn-add-decompte" (click)="ajouterDecompte()" [disabled]="decomptes.length >= 20">
            ➕ Ajouter un décompte
          </button>
        </div>

        <div class="decompte-list" *ngIf="decomptes.length > 0">
          <div class="decompte-item" *ngFor="let d of decomptes; let i = index">
            <span class="decompte-numero">N°{{ d.numero }}</span>
            <div class="decompte-fields">
              <input type="number" [(ngModel)]="d.montant" [ngModelOptions]="{standalone: true}" placeholder="Montant FCFA" class="decompte-input">
              <input type="date" [(ngModel)]="d.date" [ngModelOptions]="{standalone: true}" class="decompte-input">
            </div>
            <button type="button" class="btn-remove-decompte" (click)="supprimerDecompte(i)">✕</button>
          </div>
        </div>
        <div *ngIf="decomptes.length === 0" style="color: #6b7a8f; font-style: italic; padding: 10px 0;">
          Aucun décompte ajouté.
        </div>
      </div>

      <!-- ===== RÉCEPTION ===== -->
      <div class="form-group full-width" style="border-top: 2px dashed #e5e7eb; padding-top: 15px; margin-top: 10px;">
        <label style="font-size: 1rem; font-weight: 600; color: #1e3c72;">📦 Réception</label>
        <div class="reception-group">
          <select [(ngModel)]="typeReception" (change)="onTypeReceptionChange()" [ngModelOptions]="{standalone: true}" class="form-control">
            <option value="AUCUNE">Aucune</option>
            <option value="PROVISOIRE">Provisoire</option>
            <option value="DEFINITIVE">Définitive</option>
          </select>
          <input type="date" [(ngModel)]="dateReception" [ngModelOptions]="{standalone: true}" class="form-control" [disabled]="typeReception === 'AUCUNE'">
        </div>
      </div>

      <!-- ===== PIÈCES JOINTES ===== -->
      <div class="form-group full-width" style="border-top: 2px dashed #e5e7eb; padding-top: 15px; margin-top: 10px;">
        <label style="font-size: 1rem; font-weight: 600; color: #1e3c72;">📎 Pièces jointes</label>

        <!-- Espace de stockage -->
        <div class="storage-info">
          <span>💾 Espace utilisé : {{ getEspaceUtilise() }} Go / {{ getEspaceTotal() }} Go</span>
          <div class="progress-bar">
            <div class="progress-fill" [style.width.%]="getPourcentageEspace()"></div>
          </div>
        </div>

        <!-- Zone de drop -->
        <div class="file-drop-zone" 
             (dragover)="onDragOver($event)" 
             (dragleave)="onDragLeave($event)" 
             (drop)="onDropFile($event)"
             [class.dragover]="isDragging">
          <div class="file-drop-content">
            <span class="file-icon">📂</span>
            <p>Glissez vos fichiers ici ou</p>
            <button type="button" class="btn-browse" (click)="fileInput.click()">Parcourir</button>
            <input #fileInput type="file" multiple (change)="onFileSelected($event)" style="display: none">
            <div class="file-formats">
              <span class="format-tag">PDF</span>
              <span class="format-tag">DOC</span>
              <span class="format-tag">DOCX</span>
              <span class="format-tag">XLS</span>
              <span class="format-tag">XLSX</span>
              <span class="format-tag">PPT</span>
              <span class="format-tag">JPG</span>
              <span class="format-tag">PNG</span>
              <span class="format-tag">ZIP</span>
              <span class="format-tag">MP4</span>
              <span class="format-tag">MP3</span>
            </div>
          </div>
        </div>

        <!-- Fichiers sélectionnés (à uploader) -->
        <div class="file-list" *ngIf="fichiersSelectionnes.length > 0">
          <div class="file-item" *ngFor="let file of fichiersSelectionnes; let i = index">
            <span class="file-name">{{ file.name }}</span>
            <span class="file-size">{{ file.size | fileSize }}</span>
            <button type="button" class="btn-remove-file" (click)="removeFileSelection(i)">✕</button>
          </div>
        </div>

        <!-- Fichiers déjà uploadés -->
        <div class="file-list uploaded" *ngIf="fichiers.length > 0">
          <h4>📁 Fichiers téléchargés</h4>
          <div class="file-item uploaded-item" *ngFor="let f of fichiers; let i = index">
            <span class="file-icon-small">{{ getIcone(f.type) }}</span>
            <span class="file-name">{{ f.nom }}</span>
            <span class="file-size">{{ f.taille | fileSize }}</span>
            <span class="file-date">{{ f.dateUpload | date:'dd/MM/yyyy HH:mm' }}</span>
            <div class="file-actions">
              <button class="btn-download" (click)="telechargerFichier(marcheId!, f.id!, f.nom)" title="Télécharger">⬇️</button>
              <button class="btn-view" (click)="visualiserFichier(f.chemin)" title="Visualiser">👁️</button>
              <button class="btn-delete" (click)="supprimerFichier(marcheId!, f.id!, i)" title="Supprimer">🗑️</button>
            </div>
          </div>
        </div>
      </div>

    </div>

    <div class="form-actions">
      <button type="button" class="btn btn-secondary" (click)="goBack()">Annuler</button>
      <button type="submit" class="btn btn-primary" [disabled]="marcheForm.invalid || isLoading">
        <span *ngIf="!isLoading">{{ isEditMode ? 'Mettre à jour' : 'Créer' }}</span>
        <span *ngIf="isLoading">⏳ En cours...</span>
      </button>
    </div>
  </form>
</div>
